"""Core bubble sort helpers."""

from __future__ import annotations

from dataclasses import dataclass
from collections.abc import Callable, Iterable, MutableSequence
from operator import gt, lt
from typing import Any, Protocol, TypeVar, overload

__all__ = ["bubbleSort", "bubble_sort", "bubble_sorted"]


class _SupportsOrder(Protocol):
    def __lt__(self, other: Any, /) -> bool: ...

    def __gt__(self, other: Any, /) -> bool: ...


T = TypeVar("T")
ComparableT = TypeVar("ComparableT", bound=_SupportsOrder)


@dataclass(slots=True)
class _ComparisonState:
    comparison_values: list[Any]
    should_swap: Callable[[Any, Any], bool]

    @classmethod
    def from_values(
        cls,
        values: Iterable[T],
        key: Callable[[T], Any] | None,
        reverse: bool,
    ) -> "_ComparisonState":
        if key is None:
            comparison_values = list(values)
        else:
            comparison_values = [key(value) for value in values]

        return cls(comparison_values, lt if reverse else gt)


def _bubble_pass(
    values: MutableSequence[T],
    comparison_values: list[Any],
    unsorted_limit: int,
    should_swap: Callable[[Any, Any], bool],
) -> int | None:
    last_swap_index: int | None = None

    for index in range(unsorted_limit):
        if should_swap(comparison_values[index], comparison_values[index + 1]):
            values[index], values[index + 1] = values[index + 1], values[index]
            comparison_values[index], comparison_values[index + 1] = (
                comparison_values[index + 1],
                comparison_values[index],
            )
            last_swap_index = index

    return last_swap_index


@overload
def bubble_sort(
    values: MutableSequence[ComparableT],
    *,
    key: None = None,
    reverse: bool = False,
) -> None: ...


@overload
def bubble_sort(
    values: MutableSequence[T],
    *,
    key: Callable[[T], ComparableT],
    reverse: bool = False,
) -> None: ...


def bubble_sort(
    values: MutableSequence[T],
    *,
    key: Callable[[T], Any] | None = None,
    reverse: bool = False,
) -> None:
    """Sort values in place using bubble sort."""

    unsorted_limit = len(values) - 1

    if unsorted_limit <= 0:
        return

    comparison_state = _ComparisonState.from_values(values, key, reverse)

    while unsorted_limit > 0:
        last_swap_index = _bubble_pass(
            values,
            comparison_state.comparison_values,
            unsorted_limit,
            comparison_state.should_swap,
        )

        if last_swap_index is None:
            return

        unsorted_limit = last_swap_index


@overload
def bubble_sorted(
    values: Iterable[ComparableT],
    *,
    key: None = None,
    reverse: bool = False,
) -> list[ComparableT]: ...


@overload
def bubble_sorted(
    values: Iterable[T],
    *,
    key: Callable[[T], ComparableT],
    reverse: bool = False,
) -> list[T]: ...


def bubble_sorted(
    values: Iterable[T],
    *,
    key: Callable[[T], Any] | None = None,
    reverse: bool = False,
) -> list[T]:
    """Return a sorted copy without mutating the input."""

    copied_values = list(values)
    bubble_sort(copied_values, key=key, reverse=reverse)
    return copied_values


bubbleSort = bubble_sort

